inWhere.sql:
SELECT customer_id, updated_at, email
FROM customer_updates
WHERE ROW_NUMBER() OVER (
  PARTITION BY customer_id
  ORDER BY updated_at DESC
) = 1;

distinctOn.sql:
SELECT DISTINCT ON (customer_id) customer_id, updated_at, email
FROM customer_updates
ORDER BY customer_id, updated_at DESC;

qualify.sql:
SELECT customer_id, updated_at, email
FROM customer_updates
QUALIFY ROW_NUMBER() OVER (
  PARTITION BY customer_id
  ORDER BY updated_at DESC
) = 1;

pageSeries.sql:
WITH bounds AS (SELECT MIN(login_date) AS lo, MAX(login_date) AS hi FROM logins)
SELECT CAST(g AS DATE) AS day
FROM bounds, generate_series(bounds.lo, bounds.hi, INTERVAL '1 day') AS gs(g);

summed.sql:
SELECT SUM(users) AS summed_daily FROM (
  SELECT COUNT(DISTINCT user_id) AS users
  FROM logins
  GROUP BY login_date
) d;

repeat.sql:
SELECT COUNT(*) AS users, SUM(days - 1) AS extra_counts FROM (
  SELECT user_id, COUNT(DISTINCT login_date) AS days
  FROM logins
  GROUP BY user_id
  HAVING COUNT(DISTINCT login_date) > 1
) r;

