cte.sql:
WITH recent AS (
  SELECT * FROM customer_updates
  WHERE updated_at >= TIMESTAMP '2024-05-01'
)
SELECT * FROM recent
ORDER BY updated_at;

recursive.sql:
WITH RECURSIVE nums(n) AS (
  SELECT 1
  UNION ALL
  SELECT n + 1 FROM nums WHERE n < 5
)
SELECT * FROM nums;

pivotClause.sql:
SELECT *
FROM sales
PIVOT (SUM(amount) FOR quarter IN ('Q1', 'Q2'));

both.sql:
SELECT COUNT(DISTINCT user_id) AS exact,
  approx_count_distinct(user_id) AS approx
FROM ids;
